export async function listTools() {
  return [
    {
      name: 'audit_page',
      description: 'Paginate audit records with opaque cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          limit: { type: 'integer', minimum: 1, maximum: 3 },
          cursor: { type: 'string' }
        },
        required: ['limit'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'audit_page') {
    throw rpcError(-32601, `Unknown tool: ${name}`);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw rpcError(-32602, 'Invalid arguments: expected an object');
  }

  const allowed = new Set(['limit', 'cursor']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw rpcError(-32602, `Unexpected field: ${key}`);
    }
  }

  const { limit, cursor } = args;

  if (limit === undefined || limit === null) {
    throw rpcError(-32602, 'limit is required');
  }
  if (
    typeof limit !== 'number' ||
    !Number.isInteger(limit) ||
    limit < 1 ||
    limit > 3
  ) {
    throw rpcError(-32602, 'limit must be an integer between 1 and 3');
  }

  let offset = 0;
  if (cursor !== undefined && cursor !== null) {
    if (typeof cursor !== 'string') {
      throw rpcError(-32602, 'Malformed cursor');
    }
    const m = /^c(\d+)$/.exec(cursor);
    if (!m || cursor !== `c${Number(m[1])}`) {
      throw rpcError(-32602, 'Malformed cursor');
    }
    const n = Number(m[1]);
    offset = (n + 1) * limit;
    if (offset >= RECORDS.length) {
      throw rpcError(-32602, 'Unknown cursor');
    }
  }

  const slice = RECORDS.slice(offset, offset + limit);
  const hasMore = offset + limit < RECORDS.length;
  const nextCursor = hasMore ? `c${Math.floor(offset / limit)}` : null;

  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ records: slice, next_cursor: nextCursor })
      }
    ]
  };
}
"}

